from __future__ import annotations

import re
from rapidfuzz import fuzz, process

# Minimum RapidFuzz score (0-100) required to accept a correction.
_MIN_SCORE = 60

# Patterns stripped before matching: dosage amounts and pharmaceutical form words.
_STRIP_RE = re.compile(
    r"\b\d+\s*(?:mg|mcg|ug|g|ml|iu|units?|%)\b"
    r"|\b(?:tab(?:let)?s?|cap(?:sule)?s?|syrup|susp(?:ension)?"
    r"|inj(?:ection)?|amp(?:oule)?s?|vial|drop|patch"
    r"|cream|ointment|gel|solution|powder|sachet|lozenge)\b",
    re.IGNORECASE,
)

