# Total active drugs: 11454





class DrugValidator:
    """Validates OCR-extracted drug names against the Philippine drug lexicon."""

    _MIN_BRAND_SCORE = 88
    _MIN_RAW_RATIO   = 75
    _COMBINATION_SEPARATOR_RE = re.compile(r"\s*(?:\+|/|&|-|\bplus\b)\s*", re.IGNORECASE)

    # OCR correction patterns
    _OCR_RN_M_RE    = re.compile(r'rn')
    _OCR_DIGIT_O_RE = re.compile(r'(?<![0-9])0(?=[a-z])')
    _OCR_DIGIT_L_RE = re.compile(r'(?<=[a-z])1(?=[a-z])')
    _OCR_DIGIT_S_RE = re.compile(r'(?<=[a-z])5(?=[a-z])')

    @classmethod
    def use_database_catalog(cls, catalog: list[tuple]) -> int:
        """Replace runtime matching indexes with names loaded from the database."""
        names: list[str] = []
        brand_map: dict[str, str] = {}
        seen: set[str] = set()

        for entry in catalog:
            if len(entry) == 4:
                _, name, drug_type, _ = entry
            else:
                name, drug_type = entry
            normalized = name.strip().lower()
            if not normalized or normalized in seen:
                continue
            seen.add(normalized)
            names.append(name.strip())
            if str(drug_type).lower() == 'brand':
                brand_map[normalized] = name.strip()

        if not names:
            return 0

        lower_names = [name.lower() for name in names]
        cls._DRUG_LEXICON = names
        cls._LEXICON_LOWER = lower_names
        cls._LEXICON_LOWER_SET = frozenset(lower_names)
        cls._BRAND_TO_GENERIC = brand_map
        cls._BRAND_KEYS = list(brand_map)
        cls._BRAND_SET = frozenset(brand_map)
        cls._EXTENDED_DRUG_LEXICON = names
        cls._EXTENDED_LEXICON_LOWER = lower_names
        cls._COMBINATION_LOOKUP = {
            cls._canonicalize_combination(name): name
            for name in names
        }
        cls._MIMS_BRAND_MAP = {}
        cls._MIMS_BRAND_KEYS = []
        cls._MIMS_BRAND_SET = frozenset()
        return len(names)

    def _preprocess(self, text: str) -> str:
        """Strip dosage/form tokens and normalise whitespace."""
        cleaned = self._STRIP_RE.sub(" ", text)
        return " ".join(cleaned.split())

    @classmethod
    def _canonicalize_combination(cls, text: str) -> str:
        """Use one separator form for combination drugs written by OCR."""
        canonical = cls._COMBINATION_SEPARATOR_RE.sub(" + ", text.lower())
        return " ".join(canonical.split())

    @staticmethod
    def _normalize_name_key(text: str) -> str:
        """Collapse separator variations so hyphen/space/plus forms compare as one drug name."""
        normalized = re.sub(r"[\s\-/+&]+", " ", (text or "").lower())
        return " ".join(normalized.split())

    def _ocr_correct(self, text: str) -> str:
        """Apply common OCR character substitutions to a lowercase string."""
        text = self._OCR_RN_M_RE.sub('m', text)
        text = self._OCR_DIGIT_O_RE.sub('o', text)
        text = self._OCR_DIGIT_L_RE.sub('l', text)
        text = self._OCR_DIGIT_S_RE.sub('s', text)
        return text

    def _validate_drug_name(self, raw_text: str) -> dict[str, object]:
        """
        Validate a raw OCR drug name against the Philippine drug lexicon.

        Resolution order:
          1. Exact brand-name lookup  -- O(1) set check, returns the mapped generic.
          2. Fuzzy brand-name lookup  -- catches OCR-garbled brand names.
          3. Fuzzy generic match      -- WRatio + token_set_ratio on the original
                                        and OCR-corrected query variants.

        Returns
        -------
        dict with keys:
            original   -- input text as-is
            corrected  -- resolved generic name (or original if no match)
            confidence -- float 0.0-1.0
            matched    -- True if a match above the confidence threshold was found
            match_type -- "brand_exact" | "brand_fuzzy" | "generic_fuzzy" | None
        """
        original = raw_text.strip()
        cleaned = self._preprocess(original)

        if not cleaned:
            return {"original": original, "corrected": original,
                    "confidence": 0.0, "matched": False, "match_type": None}

        cleaned_lower = cleaned.lower()
        ocr_fixed = self._ocr_correct(cleaned_lower)
        queries: list[str] = [cleaned_lower]
        if ocr_fixed != cleaned_lower:
            queries.append(ocr_fixed)

        # OCR commonly writes combination drugs with '/' while the catalog uses '+'.
        # Resolve this before fuzzy matching so a valid combination is not discarded
        # because a different catalog entry happens to score higher.
        for q in queries:
            canonical = self._canonicalize_combination(q)
            canonical_match = self._COMBINATION_LOOKUP.get(canonical)
            if canonical_match is not None:
                return {
                    "original": original,
                    "corrected": canonical_match,
                    "confidence": 1.0,
                    "matched": True,
                    "match_type": "generic_exact",
                }

        normalized_query = self._normalize_name_key(cleaned_lower)
        for candidate in self._EXTENDED_DRUG_LEXICON:
            if self._normalize_name_key(candidate) == normalized_query:
                return {
                    "original": original,
                    "corrected": candidate,
                    "confidence": 1.0,
                    "matched": True,
                    "match_type": "generic_exact",
                }

        # 1. Exact brand lookup -- O(1), curated map then MIMS brand set.
        for q in queries:
            if q in self._BRAND_SET:
                return {
                    "original": original,
                    "corrected": self._BRAND_TO_GENERIC[q],
                    "confidence": 1.0,
                    "matched": True,
                    "match_type": "brand_exact",
                }
            if q in self._MIMS_BRAND_SET:
                return {
                    "original": original,
                    "corrected": self._MIMS_BRAND_MAP[q],
                    "confidence": 1.0,
                    "matched": True,
                    "match_type": "mims_brand_exact",
                }

        # 2. Fuzzy brand lookup -- curated brands first, then MIMS brands.
        for q in queries:
            result = process.extractOne(
                q,
                self._BRAND_KEYS,
                scorer=fuzz.WRatio,
                score_cutoff=self._MIN_BRAND_SCORE,
            )
            if result is not None:
                brand, score, _ = result
                if fuzz.ratio(q, brand) >= self._MIN_RAW_RATIO:
                    return {
                        "original": original,
                        "corrected": self._BRAND_TO_GENERIC[brand],
                        "confidence": round(score / 100.0, 4),
                        "matched": True,
                        "match_type": "brand_fuzzy",
                        "algorithm_used": "WRatio",
                    }

            result = process.extractOne(
                q,
                self._MIMS_BRAND_KEYS,
                scorer=fuzz.WRatio,
                score_cutoff=self._MIN_BRAND_SCORE,
            )
            if result is not None:
                brand, score, _ = result
                # Avoid false positives where a generic is a token inside a
                # manufacturer-prefixed brand (e.g. "amoxicillin" in "boie amoxicillin").
                generic_check = process.extractOne(
                    q, self._EXTENDED_LEXICON_LOWER, scorer=fuzz.ratio, score_cutoff=90
                )
                if (
                    generic_check is None
                    and fuzz.ratio(q, brand) >= self._MIN_RAW_RATIO
                ):
                    return {
                        "original": original,
                        "corrected": self._MIMS_BRAND_MAP[brand],
                        "confidence": round(score / 100.0, 4),
                        "matched": True,
                        "match_type": "mims_brand_fuzzy",
                        "algorithm_used": "WRatio",
                    }

        # 3. Fuzzy generic match -- extended lexicon includes MIMS generics.
        best = None
        best_algorithm = None
        for q in queries:
            for scorer, algorithm in (
                (fuzz.WRatio, "WRatio"),
                (fuzz.token_set_ratio, "token_set_ratio"),
            ):
                result = process.extractOne(
                    q,
                    self._EXTENDED_LEXICON_LOWER,
                    scorer=scorer,
                    score_cutoff=self._MIN_SCORE,
                )
                if result and (best is None or result[1] > best[1]):
                    best = result
                    best_algorithm = algorithm

        if best is None:
            return {"original": original, "corrected": original,
                    "confidence": 0.0, "matched": False, "match_type": None}

        _, score, idx = best
        corrected = self._EXTENDED_DRUG_LEXICON[idx]

        raw_sim = max(fuzz.ratio(q, corrected.lower()) for q in queries)
        if raw_sim < self._MIN_RAW_RATIO:
            return {"original": original, "corrected": original,
                    "confidence": 0.0, "matched": False, "match_type": None}

        return {
            "original": original,
            "corrected": corrected,
            "confidence": round(score / 100.0, 4),
            "matched": True,
            "match_type": "generic_fuzzy",
            "algorithm_used": best_algorithm,
        }

    _product_catalog = None

    @classmethod
    def use_product_catalog(cls, catalog):
        cls._product_catalog = catalog
        names = {}
        brands = {}
        for product in catalog.products.values():
            generic, brand = product['generic_name'], product['brand_name']
            for name in (generic, brand):
                if name:
                    names.setdefault(name.lower(), name)
            if brand:
                brands.setdefault(brand.lower(), set()).add(generic or brand)
        cls.use_database_catalog([(name, 'generic') for name in names.values()])
        # Only unambiguous brand-to-ingredient relationships enter parser lookup.
        cls._BRAND_TO_GENERIC = {b: next(iter(g)) for b, g in brands.items() if len(g) == 1}
        cls._BRAND_KEYS = list(cls._BRAND_TO_GENERIC)
        cls._BRAND_SET = frozenset(cls._BRAND_KEYS)

    def validate_drug_name(self, raw_text: str, **context) -> dict[str, object]:
        if self._product_catalog is not None:
            return self._product_catalog.match(raw_text, **context)
        result = self._validate_drug_name(raw_text)
        matched = bool(result.get("matched"))
        match_type = result.get("match_type")
        corrected = str(result.get("corrected") or "")
        original = str(result.get("original") or raw_text)
        raw_score = 100.0 if matched and match_type and str(match_type).endswith("exact") else (
            round(float(result.get("confidence") or 0.0) * 100.0, 4) if matched else 0.0
        )
        cutoff_by_type = {
            "brand_fuzzy": self._MIN_BRAND_SCORE,
            "mims_brand_fuzzy": self._MIN_BRAND_SCORE,
            "generic_fuzzy": self._MIN_SCORE,
            "brand_exact": 100,
            "mims_brand_exact": 100,
            "generic_exact": 100,
        }
        algorithm_by_type = {
            "brand_exact": "exact",
            "mims_brand_exact": "exact",
            "generic_exact": "exact",
        }
        result.update(
            raw_score=raw_score if matched else None,
            token_sort_ratio=(
                int(fuzz.token_sort_ratio(original, corrected)) if matched else None
            ),
            partial_ratio=(
                int(fuzz.partial_ratio(original, corrected)) if matched else None
            ),
            algorithm_used=(
                result.get("algorithm_used")
                or algorithm_by_type.get(str(match_type))
            ) if matched else None,
            score_cutoff_used=cutoff_by_type.get(str(match_type)) if matched else None,
        )
        return result

    def validate_drug_names(self, raw_texts: list[str]) -> list[dict[str, object]]:
        """Batch wrapper -- validate a list of OCR drug name strings."""
        return [self.validate_drug_name(t) for t in raw_texts]


# -- Attach module-level data as class attributes ---------------------------------
# Derived lookup structures (built once at import time from the raw data above).
_BRAND_KEYS: list[str] = list(_BRAND_TO_GENERIC.keys())
_BRAND_SET: frozenset[str] = frozenset(_BRAND_TO_GENERIC.keys())

_MIMS_BRAND_MAP: dict[str, str] = {entry[0].lower(): entry[0] for entry in _MIMS_BRANDS}
_MIMS_BRAND_KEYS: list[str] = list(_MIMS_BRAND_MAP.keys())
_MIMS_BRAND_SET: frozenset[str] = frozenset(_MIMS_BRAND_MAP.keys())

_LEXICON_LOWER_SET: frozenset[str] = frozenset(_LEXICON_LOWER)
_EXTENDED_DRUG_LEXICON: list[str] = list(_DRUG_LEXICON) + [
    g for g in _MIMS_GENERICS if g.lower() not in _LEXICON_LOWER_SET
]
_EXTENDED_LEXICON_LOWER: list[str] = [d.lower() for d in _EXTENDED_DRUG_LEXICON]

# Attach data to the class so callers can reference DrugValidator._DRUG_LEXICON etc.
DrugValidator._MIN_SCORE              = _MIN_SCORE
DrugValidator._STRIP_RE               = _STRIP_RE
DrugValidator._DRUG_LEXICON           = _DRUG_LEXICON
DrugValidator._LEXICON_LOWER          = _LEXICON_LOWER
DrugValidator._BRAND_TO_GENERIC       = _BRAND_TO_GENERIC
DrugValidator._LEXICON_LOWER_SET      = _LEXICON_LOWER_SET
DrugValidator._EXTENDED_DRUG_LEXICON  = _EXTENDED_DRUG_LEXICON
DrugValidator._EXTENDED_LEXICON_LOWER = _EXTENDED_LEXICON_LOWER
DrugValidator._COMBINATION_LOOKUP    = {
    DrugValidator._canonicalize_combination(name): name
    for name in _EXTENDED_DRUG_LEXICON
}
DrugValidator._BRAND_KEYS             = _BRAND_KEYS
DrugValidator._BRAND_SET              = _BRAND_SET
DrugValidator._MIMS_BRAND_MAP         = _MIMS_BRAND_MAP
DrugValidator._MIMS_BRAND_KEYS        = _MIMS_BRAND_KEYS
DrugValidator._MIMS_BRAND_SET         = _MIMS_BRAND_SET

# Module-level singleton -- preserves existing imports:
#   from drug_validator import validate_drug_name
#   from drug_validator import _DRUG_LEXICON, _LEXICON_LOWER, _BRAND_TO_GENERIC
_drug_validator = DrugValidator()
validate_drug_name  = _drug_validator.validate_drug_name
validate_drug_names = _drug_validator.validate_drug_names
